-- GenDB engine variant Q16-wrapped_tables: template q16.sql, kind wrapped_tables (generated by generate.py; frozen)
SELECT
  p_brand,
  p_type,
  p_size,
  COUNT(DISTINCT ps_suppkey) AS supplier_cnt
FROM (
  SELECT
    *
  FROM partsupp
) AS partsupp, (
  SELECT
    *
  FROM part
) AS part
WHERE
  p_partkey = ps_partkey
  AND p_brand <> $1
  AND NOT p_type LIKE $2
  AND p_size IN ($3, $4, $5, $6, $7, $8, $9, $10)
  AND NOT ps_suppkey IN (
    SELECT
      s_suppkey
    FROM (
      SELECT
        *
      FROM supplier
    ) AS supplier
    WHERE
      s_comment LIKE '%Customer%Complaints%'
  )
GROUP BY
  p_brand,
  p_type,
  p_size
ORDER BY
  supplier_cnt DESC,
  p_brand,
  p_type,
  p_size
